abstract class Shape { public abstract double Area(); }

sealed class Circle : Shape
{
    public double R;
    public override double Area() => Math.PI * R * R;
}

double One(Circle c) => c.Area(); // exactly Circle: a direct call
double Any(Shape s) => s.Area();  // type unknown: a call through the method table

